(2866, 'S01-SAL-027', 'Sales & Revenue', 'Do you know your own close rate, or would you have to guess?', 16, 169, 'open_text', 2, 'CORE', false, NULL, 'Stage 0→1', NULL, NULL, NULL),
(2867, 'S01-SAL-028', 'Sales & Revenue', 'Has someone else on your team ever closed a deal you couldn''t, and do you know why?', 16, 179, 'open_text', 3, 'SUPPLEMENTARY', false, NULL, 'Stage 0→1', NULL, NULL, NULL),
