(2870, 'S01-SAL-031', 'Sales & Revenue', 'If your best customer explained why they bought, would it match what you think you sold them on?', 16, 171, 'open_text', 2, 'CORE', false, NULL, 'Stage 0→1', NULL, NULL, NULL),
(2871, 'S01-SAL-032', 'Sales & Revenue', 'Is there a skill gap in how your team sells that''s costing you deals you should be winning?', 16, 169, 'open_text', 2, 'CORE', false, NULL, 'Stage 0→1', NULL, NULL, NULL),
