(2873, 'S01-SAL-034', 'Sales & Revenue', 'What would change about your close rate if everyone on your team sold as well as your best person?', 16, 179, 'open_text', 3, 'CORE', false, NULL, 'Stage 0→1', NULL, NULL, NULL),
