(2876, 'S01-SLX-001', 'Sales Execution', 'Do you have a reusable template for proposals, or does every one get built from scratch?', 158, 1197, 'open_text', 2, 'CORE', false, NULL, 'Stage 0→1', NULL, NULL, NULL),
(2877, 'S01-SLX-002', 'Sales Execution', 'How long does it typically take you to send a proposal after a conversation, and is that fast enough?', 158, 1198, 'open_text', 2, 'CORE', false, NULL, 'Stage 0→1', NULL, NULL, NULL),
(2878, 'S01-SLX-003', 'Sales Execution', 'Does your proposal actually reflect what was discussed on the call, or does it feel generic?', 158, 1199, 'open_text', 2, 'CORE', false, NULL, 'Stage 0→1', NULL, NULL, NULL),
(2879, 'S01-SLX-004', 'Sales Execution', 'Is there a clear, consistent way you present pricing, or does it vary each time?', 158, 1200, 'open_text', 2, 'CORE', false, NULL, 'Stage 0→1', NULL, NULL, NULL),
(2880, 'S01-SLX-005', 'Sales Execution', 'What happens after you send a proposal — is there a follow-up process, or does it just wait for a reply?', 158, 1201, 'open_text', 2, 'CORE', false, NULL, 'Stage 0→1', NULL, NULL, NULL),
